-- 885: Move the Certification section out of short_description into the
-- per-course `course_<sku>_certification` cms/block, so the storefront
-- Certification card renders FROM the CMS block instead of from hardcoded
-- template copy. Generated by
-- scripts/local-dev/generate-certification-to-cms-block-migration.php
--
-- Content is canonical per course type (the legacy description copy was
-- inconsistent: 'Tertiary Infotech' vs 'Tertiary Courses', and stray
-- OpenCerts bullets on non-WSQ courses):
--   WSQ (TGS-*, not CASL) -> Certificate of Completion + OpenCerts
--   CASL / non-WSQ        -> Certificate of Completion only
-- Any existing 'Certification Exam at Pearson Vue' supplement (migration
-- 151) is preserved verbatim.
--
-- Every literal is hex-encoded so apply.php's utf8 PDO connection cannot
-- hit error 1366 on legacy bytes (feedback_migration_applyphp_utf8_outage).
-- Idempotent: re-running rewrites the same block content and the same
-- already-stripped description. Partner-safe (SKU-driven, no store guard
-- needed — each site only holds its own SKUs).
--
-- courses: 626  (WSQ 265 / CASL 13 / non-WSQ 348)  pearson-vue preserved: 0

SET @a_sdesc := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'short_description');

--  C1235
INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active)
  SELECT 0x436f757273652020433132333520e280942043657274696669636174696f6e, 0x636f757273655f2043313233355f63657274696669636174696f6e, , NOW(), NOW(), 1 FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM cms_block WHERE identifier = 0x636f757273655f2043313233355f63657274696669636174696f6e);
UPDATE cms_block SET content = , is_active = 1, update_time = NOW() WHERE identifier = 0x636f757273655f2043313233355f63657274696669636174696f6e;
INSERT IGNORE INTO cms_block_store (block_id, store_id)
  SELECT block_id, 0 FROM cms_block WHERE identifier = 0x636f757273655f2043313233355f63657274696669636174696f6e;
UPDATE catalog_product_entity_text SET value =  WHERE attribute_id = @a_sdesc AND store_id = 0 AND entity_id = 1235;

